import*as THREE from'three';import{Port,materials}from'../../core/index.js';import{mesh,FACE,portQuaternion}from'../../modeling/parts.js';import{spec}from'./dimensions.js';const tau=Math.PI*2;const hole=(s,x,y,r)=>{const h=new THREE.Path();h.absarc(x,y,r,0,tau,false);s.holes.push(h);};const solid=(p,s,d,v,m,n)=>mesh(p,new THREE.ExtrudeGeometry(s,{depth:d,bevelEnabled:false,curveSegments:64}),m,v,n);function annulus(p,outer,inner,depth,pos,mat,name){const s=new THREE.Shape();s.absarc(0,0,outer,0,tau,false);hole(s,0,0,inner);return solid(p,s,depth,pos,mat,name);}
export function sma(host){
 const g=new THREE.Group();g.name='ZigBee SMA female appearance connector';g.position.fromArray(spec.sma.position);g.quaternion.copy(FACE.top);host.body.add(g);const gold=materials.metal(0xd1b85c,{roughness:.36}),white=materials.plastic(0xdcd9ba,{roughness:.75}),dark=materials.plastic(0x252b22,{roughness:.8});
 const barrel=annulus(g,2.78,2.1,10.3,[0,0,-10.3],gold,'ZigBee SMA continuous annular female outer barrel');
 const lip=annulus(g,2.78,2.1,.45,[0,0,-.45],gold,'ZigBee SMA open annular mating lip');
 class ThreadCurve extends THREE.Curve{getPoint(t,target=new THREE.Vector3()){const a=t*tau*9;return target.set(Math.cos(a)*2.94,Math.sin(a)*2.94,-7.2+t*6.3);}}
 const thread=mesh(g,new THREE.TubeGeometry(new ThreadCurve(),648,.16,8,false),gold,[0,0,0],'ZigBee SMA real continuous helical external thread');
 const hex=new THREE.Shape();for(let i=0;i<6;i++){const a=tau*i/6+Math.PI/6;const x=Math.cos(a)*3.13,y=Math.sin(a)*3.13;i?hex.lineTo(x,y):hex.moveTo(x,y);}hex.closePath();hole(hex,0,0,1.05);const nut=solid(g,hex,4,[0,0,-13.4],gold,'ZigBee SMA retained internal hex body visible through both native windows');
 const dielectric=annulus(g,2.095,.6,4.35,[0,0,-4.55],white,'ZigBee SMA recessed PTFE insulator with genuine centre bore');
 const contact=annulus(g,.58,.25,4,[0,0,-4.4],gold,'ZigBee SMA female hollow recessed centre contact sleeve');
 const stop=mesh(g,new THREE.CylinderGeometry(.25,.25,.12,32).rotateX(Math.PI/2),gold,[0,0,-4.56],'ZigBee SMA recessed centre contact blind end');
 const shoulder=annulus(g,1.04,.55,1.2,[0,0,-14.4],white,'ZigBee SMA rear feed-through dielectric');const rearPin=mesh(g,new THREE.CylinderGeometry(.24,.24,1.6,24).rotateX(Math.PI/2),gold,[0,0,-14.4],'ZigBee SMA rear centre terminal');
 const rear=annulus(g,1.45,.62,1.2,[0,0,-15],gold,'ZigBee SMA rear coax termination sleeve');
 const cablePath=new THREE.CatmullRomCurve3([new THREE.Vector3(0,24.3,0),new THREE.Vector3(0,22.2,.1),new THREE.Vector3(5.5,20,.4),new THREE.Vector3(8,15.8,.3),new THREE.Vector3(6,19,.05)]);const coax=mesh(host.body,new THREE.TubeGeometry(cablePath,48,.5,10,false),materials.plastic(0x171e1a,{roughness:.86}),[0,0,0],'ZigBee concealed concealed SMA to module coax installation,inferred route');
 const ipg=new THREE.Group();ipg.name='ZigBee fixed miniature board coax termination,exact type unconfirmed';ipg.position.set(6,19,-.25);host.body.add(ipg);const socket=annulus(ipg,1.1,.55,.6,[0,0,0],gold,'ZigBee annular miniature coax termination envelope,installation inferred');mesh(ipg,new THREE.CylinderGeometry(.23,.23,.5,20).rotateX(Math.PI/2),gold,[0,0,.25],'ZigBee miniature coax central terminal');
 const port=host.add(new Port({id:'sma',label:'SMA female · antenna connector',connector:'sma-female',position:spec.sma.position,quaternion:portQuaternion('top'),hitSize:[6.2,1,6.2],pins:[{n:1,name:'centre ANT'},{n:2,name:'outer shield'}],meta:{role:'visual-connector',face:'top',signalRole:'antenna',scope:'Female connector shape, external thread, real recessed centre socket, pose and matching connector type only; no RF field,ZigBee,UART,RF,frequency,signal,RSSI,network,pairing,power or electrical simulation'}}));return{group:g,barrel,lip,thread,nut,dielectric,contact,stop,shoulder,rearPin,rear,coax,ipex:ipg,socket,port};
}
export function grove(host){const g=new THREE.Group();g.name='ZigBee open blue HY2.0-4P socket';g.position.fromArray(spec.grove.position);g.quaternion.copy(FACE.bottom);host.body.add(g);const plastic=materials.plastic(spec.grove.color,{roughness:.66}),metal=materials.metal(0xc0b797,{roughness:.42}),box=(s,p,n,m=plastic)=>mesh(g,new THREE.BoxGeometry(...s),m,p,'ZigBee Grove '+n),depth=6.6;
 for(const sign of[-1,1]){box([.65,5.2,depth],[sign*4.675,0,-depth/2],'side wall');box([.7,.6,3.2],[sign*3.85,2.3,-4.9],'guide rail');box([.6,.45,1.2],[sign*3.65,2.375,-1.8],'latch shoulder');}box([8.7,.65,depth],[0,-2.275,-depth/2],'floor');box([8.7,4.55,.65],[0,.325,-depth+.325],'rear wall');box([4.8,.45,2.3],[0,2.375,-4.6],'locking bridge');const contacts=[];for(let i=0;i<4;i++){contacts.push(box([.42,.42,4.7],[(i-1.5)*2,.2,-3.7],`contact ${i+1}`,metal));box([.42,1.4,.42],[(i-1.5)*2,-2.7,-6],`solder tail ${i+1}`,metal);}
 const port=host.add(new Port({id:'grove',label:'PORT.C · UART',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('bottom'),hitSize:[10,1,5.2],pins:[{n:1,name:'GND',color:'black'},{n:2,name:'5V',color:'red'},{n:3,name:'UART_RX',color:'yellow'},{n:4,name:'UART_TX',color:'white'}],meta:{role:'visual-connector',face:'bottom',scope:'Physical attachment, four contacts, pin labels and cable pose only; no UART transaction,ZigBee,RF,RSSI,network,pairing,signal,supply or electrical behavior'}}));return{group:g,contacts,port};}
